const $=s=>document.querySelector(s), root=$('#app');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',book:'M3 4h6a3 3 0 0 1 3 3v14a5 5 0 0 0-5-3H3zM21 4h-6a3 3 0 0 0-3 3v14a5 5 0 0 1 5-3h4z',game:'M7 8h10a5 5 0 0 1 5 5l-1 3a3 3 0 0 1-5 1l-3-3h-2l-3 3a3 3 0 0 1-5-1l-1-3a5 5 0 0 1 5-5zM6 11v5m-2-2h5m8-1h.1m2 2h.1',spark:'M12 2 9 9 2 12l7 3 3 7 3-7 7-3-7-3zM20 2v4m-2-2h4',pen:'M4 20l5-1L21 7l-4-4L5 15zM14 6l4 4',quiz:'M5 3h14v18H5zM8 7h8M8 12h8M8 17h5',people:'M16 21v-3a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v3M14 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-4-4M10 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',trophy:'M8 21h8m-4-5v5M7 3h10v7a5 5 0 0 1-10 0zM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4',chart:'M3 3v18h18M7 15l4-5 4 2 5-7',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zM8 12l3 3 5-6',bell:'M6 9a6 6 0 0 1 12 0v6l2 2H4l2-2zM10 21h4',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',menu:'M3 6h18M3 12h18M3 18h18',arrow:'M4 12h16m-6-6 6 6-6 6',check:'M4 12l5 5L20 6',settings:'M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bolt:'M13 2 3 14h8l-1 8 11-13h-8z',file:'M5 2h10l4 4v16H5zM14 2v5h5M8 12h8m-8 4h8'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const btn=(text,act,cls='',attrs='')=>`<button class="btn ${cls}" data-act="${act}" ${attrs}>${text}</button>`;
const field=(label,name,type='text',value='',attrs='')=>`<label class="field">${label}<input type="${type}" name="${name}" value="${e(value)}" ${attrs}></label>`;
const area=(label,name,value='',attrs='')=>`<label class="field">${label}<textarea name="${name}" ${attrs}>${e(value)}</textarea></label>`;
const select=(label,name,opts,value)=>`<label class="field">${label}<select name="${name}">${opts.map(([v,t])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
const check=(label,name,checked=false)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
const logo=()=>`<a class="logo" href="#home"><img src="/icon.svg" alt=""><span>ilmora<span>.</span></span></a>`;
const section=(title,sub='')=>`<div class="section"><h2>${title}</h2>${sub}</div>`;
const notice=(s,w=false)=>`<div class="notice ${w?'warn':''}">${s}</div>`;
const panel=(n,t,d,action)=>`<div class="panel stack"><div class="ico">${icon(n)}</div><h3>${t}</h3><p class="muted">${d}</p>${action||''}</div>`;
const get=(k,def)=>{try{return JSON.parse(localStorage.getItem('ilmora:'+k))??def}catch{return def}},save=(k,v)=>localStorage.setItem('ilmora:'+k,JSON.stringify(v));
let sb=null,user=null,profile=null,demo=false,route='landing',data={},practice=null,live=null,liveState=null,channel=null,poll=null,timer=null,selected=[],builder=[],editingQuiz=null,doc=null,messages=[],chatId=null,aiTool='chat',aiAssignment='',busyAI=false,lessonId=1,authMode='login',renderKey=0,liveRequest=false,authReady=false,cardIndex=0,cardFlip=false;
let theme=get('theme','light');document.body.classList.toggle('dark',theme==='dark');
const config=window.ILMORA_CONFIG||{};const configured=!!(config.supabaseUrl&&config.supabaseKey);
const isStaff=()=>['teacher','admin'].includes(profile?.role);
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),5000)}
function fail(err){toast(err?.message||String(err));console.error(err)}
const api=async(p,args={})=>{if(!sb)throw Error('Avval Supabase sozlanishi kerak.');const {data,error}=await sb.rpc(p,args);if(error)throw Error(error.message);return data};
async function query(table,mutator=q=>q){if(!sb)throw Error('Supabase ulanmagan.');const {data,error}=await mutator(sb.from(table));if(error)throw Error(error.message);return data}
const go=(r)=>{if(location.hash===`#${r}`)navigate();else location.hash=r};
function stopLive(){clearInterval(poll);clearInterval(timer);poll=null;timer=null;if(channel&&sb)sb.removeChannel(channel);channel=null}
const pageNames={labs:'Amaliy laboratoriya',map:'Bilim xaritasi',mistakes:'Xatolar daftari',home:'Bosh sahifa',lessons:'Darslar',lesson:'Dars',practice:'Testlar',studio:'Test yaratish',live:'Jonli o‘yin',join:'O‘yinga qo‘shilish',ai:'ILMORA AI',writing:'Writing Studio',library:'Kutubxona',citation:'Iqtiboslar',cards:'Kartochkalar',classes:'Guruhlar',assignments:'Topshiriqlar',leader:'Reyting',stats:'Statistika',profile:'Profil',admin:'Admin panel',notifications:'Bildirishnomalar',feedback:'Fikr-mulohaza',auth:'Kirish',shared:'Ulashilgan hujjat',game:'Jonli o‘yin',landing:'ILMORA'};
const navs=[['TA’LIM',[['home','home'],['lessons','book'],['practice','quiz'],['cards','bolt'],['labs','pen'],['map','chart'],['mistakes','quiz'],['library','book']]],['YARATISH',[['live','game'],['studio','quiz'],['ai','spark'],['writing','pen'],['citation','file']]],['HAMKORLIK',[['classes','people'],['assignments','file'],['leader','trophy'],['stats','chart']]],['SOZLAMALAR',[['profile','settings'],['feedback','bell']]]];
function shell(body){return `<div class="shell"><aside class="side" id="side">${logo()}${navs.map(([t,items])=>`<div class="navtitle">${t}</div>${items.map(([r,n])=>`<button class="nav ${route===r||(route==='lesson'&&r==='lessons')?'active':''}" data-go="${r}">${icon(n)}${pageNames[r]}</button>`).join('')}`).join('')}${profile?.role==='admin'?`<button class="nav" data-go="admin">${icon('shield')}Admin panel</button>`:''}<div class="sidefoot"><small>ILMORA · Bento Edition</small><div style="margin-top:8px">${btn('Chiqish','logout','outline small')}</div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="iconbutton mobile-only" data-act="menu" aria-label="Menyu">${icon('menu')}</button><h3 class="top-title">${pageNames[route]||'ILMORA'}</h3></div><div class="right">${demo?'<span class="pill">Mahalliy demo</span>':''}<button class="iconbutton" data-go="notifications" aria-label="Bildirishnomalar">${icon('bell')}</button><button class="iconbutton" data-act="theme" aria-label="Rang rejimi">${icon('moon')}</button><span class="avatar">${e((profile?.name||'T').slice(0,2).toUpperCase())}</span><span class="name"><strong>${e(profile?.name||'Talaba')}</strong><br><small>${({student:'Talaba',teacher:'O‘qituvchi',admin:'Admin'})[profile?.role]||''}</small></span></div></header><div class="page">${body}</div></main><nav class="bottomnav" aria-label="Mobil menyu">${[['home','home','Bosh sahifa'],['lessons','book','Darslar'],['live','game','Live'],['ai','spark','AI'],['profile','settings','Profil']].map(([r,n,t])=>`<button data-go="${r}" class="${route===r?'active':''}">${icon(n)}<span>${t}</span></button>`).join('')}<button data-act="menu">${icon('menu')}<span>Yana</span></button></nav></div>`}
const heroArt=`<svg viewBox="0 0 300 246" aria-hidden="true"><defs><pattern id="ruled" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M0 12L12 0" stroke="#d8bd79" stroke-opacity=".15"/></pattern></defs><circle cx="156" cy="123" r="109" fill="url(#ruled)" stroke="#d8bd79" stroke-opacity=".45"/><circle cx="156" cy="123" r="93" fill="none" stroke="#d8bd79" stroke-opacity=".3" stroke-dasharray="2 5"/><g transform="rotate(-10 151 130)"><rect x="62" y="65" width="172" height="143" rx="5" fill="#0e241f" stroke="#e8c984" stroke-width="2"/><rect x="72" y="55" width="162" height="143" rx="3" fill="#d8bd79" stroke="#152d26" stroke-width="2"/><path d="M78 44Q118 34 152 55Q186 34 228 44V181Q185 170 152 191Q118 170 78 181Z" fill="#f9f0d8" stroke="#152d26" stroke-width="2.5"/><path d="M152 55V191M92 76Q119 68 139 80M92 91Q119 83 139 95M92 106Q119 98 139 110M165 80Q187 68 214 76M165 95Q187 83 214 91M165 110Q187 98 214 106M165 125Q187 113 214 121" fill="none" stroke="#7f9988" stroke-width="2.5" stroke-linecap="round"/><path d="M92 129L136 130V157L92 154Z" fill="#e9ca87" stroke="#152d26" stroke-width="1.5"/><path d="M175 48V85L185 77L195 85V43" fill="#b86743" stroke="#152d26" stroke-width="1.5"/></g><g transform="rotate(33 232 133)"><path d="M225 60H239V179L232 197L225 179Z" fill="#e8c984" stroke="#152d26" stroke-width="2"/><path d="M225 70H239M225 179H239M232 76V176" stroke="#152d26" stroke-width="1.5"/></g><path d="M250 29v28m-14-14h28M36 111v18m-9-9h18" stroke="#e8c984" stroke-width="2" stroke-linecap="round"/><circle cx="49" cy="40" r="4" fill="#e8c984"/><circle cx="263" cy="192" r="4" fill="#e8c984"/></svg>`;
function landing(){return `<div class="landing"><nav class="landnav">${logo()}<div class="row"><button class="iconbutton" data-act="theme" aria-label="Rang rejimi">${icon('moon')}</button>${btn('Jonli o‘yin','join','outline')}${btn('Kirish','login')}</div></nav><div class="landhero"><div><span class="pill">AKADEMIK YOZUV · ILMORA</span><h1>Bilim ol.<br>Fikrla. <em>Yoz.</em><br>Rivojlan.</h1><p>6 ta ma’ruza, 40 ta kichik dars, 1000 ta mashq, jonli musobaqalar va akademik AI — yagona o‘quv makonida.</p><div class="row">${btn('O‘rganishni boshlash →','signup')}${btn('PIN orqali kirish','join','outline')}</div><div style="margin-top:14px">${!configured?btn('Mahalliy demoni ko‘rish','demo','secondary'):''}</div></div><div class="landvisual"><div class="land-orbit" aria-hidden="true"></div><div class="panel"><div class="row between"><span class="pill">ILMORA LIVE</span><span class="pill ok">Jonli o‘yin</span></div><h2 style="margin:14px 0">Akademik yozuvni bilasizmi?</h2><div class="grid two"><div class="btn" style="background:#d83b58">▲ Kirish</div><div class="btn" style="background:#2863d6">◆ Asosiy qism</div><div class="btn" style="background:#b57f0b">● Xulosa</div><div class="btn" style="background:#108158">■ Barchasi</div></div></div><div class="panel"><div class="row"><div class="ico" style="margin:0">${icon('spark')}</div><div><strong>ILMORA AI</strong><br><small>Akademik yozuv yordamchisi</small></div></div></div></div></div><div class="grid three">${panel('book','40 ta kichik dars','Boshlang‘ich nazariya, tushunchalar va misollar.')}${panel('game','Jonli musobaqalar','PIN-kod orqali bir xonada o‘ynash.')}${panel('pen','Writing Studio','Matn yozing, tahlil qiling va eksport qiling.')}</div><div class="section"><small>© ILMORA · Akademik yozuv platformasi</small></div></div>`}
function authPage(){return `<div class="landing"><nav class="landnav">${logo()}${btn('Jonli o‘yin','join','outline')}</nav><div class="panel auth stack"><span class="label">Xush kelibsiz</span><h1>${authMode==='signup'?'Akkaunt yarating':authMode==='reset'?'Parolni tiklash':authMode==='newpass'?'Yangi parol':'Tizimga kiring'}</h1>${!configured?notice('Supabase sozlanmagan. Haqiqiy akkauntlar uchun config.js faylini to‘ldiring.',true):''}<form class="stack" data-form="auth">${authMode==='signup'?field('Ismingiz','name','text','','required maxlength="80"'):''}${authMode!=='newpass'?field('Email','email','email','','required'):''}${authMode!=='reset'?field('Parol','password','password','','required minlength="8" autocomplete="'+(authMode==='login'?'current-password':'new-password')+'"'):''}<button class="btn block">${authMode==='signup'?'Ro‘yxatdan o‘tish':authMode==='reset'?'Havola yuborish':authMode==='newpass'?'Parolni yangilash':'Kirish'}</button></form>${authMode==='login'||authMode==='signup'?btn('Google orqali kirish','google','outline block'):''}<div class="row between">${btn(authMode==='signup'?'Akkauntim bor':'Ro‘yxatdan o‘tish',authMode==='signup'?'login':'signup','secondary small')}${btn('Parol esdan chiqdimi?','reset','outline small')}</div>${!configured?btn('Mahalliy demoni ochish','demo','secondary block'):''}</div></div>`}
function home(){let p=data.progress?.length||0,next=lessons.find(l=>!data.progress?.includes(l.id)),pct=Math.round(p/lessons.length*100);return `<div class="dashboard"><div class="dashboard-kicker"><span>ILMORA / O‘QUV MAKONI</span><span>AKADEMIK YOZUV · BENTO EDITION</span></div><div class="bento-main"><div class="hero bento-welcome"><div class="hero-copy"><div class="label">O‘RGANISH UCHUN YANGI IMKONIYAT</div><h1>Salom, ${e(profile?.name||'Talaba')}!</h1><p>O‘z fikringizni aniq ifodalang. Bugun bir qadam oldinga.</p>${btn('O‘rganishni davom ettirish →','continue')}</div><div class="orb-art" aria-hidden="true"><i></i><i></i><i></i><span>Ilm.</span></div></div><div class="panel bento-progress"><span class="label">O‘QUV YO‘LI</span><div class="journey-ring" style="--pct:${pct}%"><div><strong>${pct}%</strong><small>tugallangan</small></div></div><h3>${p} / ${lessons.length} dars</h3><p>${e(next?.title||'Barcha darslar tugallandi')}</p>${btn('Bilim xaritasi →','goto-map','outline small')}</div><div class="panel bento-xp"><div class="ico">${icon('bolt')}</div><small>XP ball</small><strong>${profile?.xp||0}</strong><span>Daraja ${Math.floor((profile?.xp||0)/200)+1}</span></div><div class="panel bento-live"><div class="ico">${icon('game')}</div><span class="label">MUSOBAQA</span><h2>ILMORA Live</h2><p>Birgalikda bilim bellashuvi.</p>${btn('PIN orqali kirish →','join','secondary')}</div><div class="panel bento-ai"><div class="ico">${icon('spark')}</div><span class="label">16 TA AI VOSITASI</span><h2>ILMORA AI</h2><p>Ma’ruzalarga tayangan yordamchi.</p>${btn('AI ni ochish →','goto-ai','secondary')}</div><div class="panel bento-write"><div class="ico">${icon('pen')}</div><h2>Writing Studio</h2><p>Yozing, tahrirlang, eksport qiling.</p>${btn('Yozishni boshlash','goto-writing','secondary')}</div><div class="panel bento-bank"><div class="ico">${icon('quiz')}</div><strong>${bank.length.toLocaleString('uz-UZ')}</strong><h3>Test mashqlari</h3>${btn('Bilimni sinash','goto-practice','outline small')}</div><div class="panel bento-labs"><div class="ico">${icon('book')}</div><h2>Amaliy laboratoriya</h2><p>Imlo, nutq, uslub va matn mashqlari.</p>${btn('Mashq qilish →','goto-labs','secondary')}</div></div>${section('6 ta asosiy ma’ruza',btn('Barcha darslar →','goto-lessons','outline small'))}<div class="grid three module-grid">${modules.map((m,i)=>moduleCard(m,i+1)).join('')}</div></div>`}
const lessonCard=l=>`<div class="panel lesson-card" data-module="${l.module||0}"><div class="row between"><span class="lesson-num">${l.module?'MA’RUZA '+l.module:'QO‘SHIMCHA'}</span>${data.progress?.includes(l.id)?'<span class="pill ok">Tugallangan</span>':''}</div><h3>${e(l.title)}</h3><p class="muted">${e(l.intro)}</p><small>5 tushuncha · 25 mashq${l.module?' · '+l.pages+'-sahifalar':''}</small>${btn('Darsni ochish','lesson','secondary',`data-id="${l.id}"`)}</div>`;
function lessonList(){let p=data.progress?.length||0;return `${section('Akademik yozuv',`<span class="pill">${p}/${lessons.length} tugallangan</span>`)}<div class="panel"><div class="row between"><p>Ma’ruza asosidagi darslar va qo‘shimcha mavzular.</p>${select('Rejim','lesson-mode',[['free','Erkin'],['ordered','Ketma-ket']],get('lesson-mode','free'))}</div><div class="progress"><i style="width:${p/lessons.length*100}%"></i></div></div>${modules.map((m,i)=>`${section(String(i+1).padStart(2,'0')+' / '+e(m))}<div class="grid three">${lessons.filter(l=>l.module===i+1).map(lessonCard).join('')}</div>`).join('')}${section('Qo‘shimcha akademik mavzular')}<div class="grid three">${lessons.filter(l=>!l.module).map(lessonCard).join('')}</div>${extraLessons()}`}
function extraLessons(){return `${section('Qo‘shimcha darslar')}${isStaff()?`<div class="panel stack"><h3>Yangi dars tayyorlash</h3><form class="stack" data-form="lesson-create">${field('Mavzu','title','text','','required maxlength="150"')}${area('Dars mazmuni','body','','required maxlength="40000"')}${field('YouTube video havolasi','video','url')}${select('Nashr turi','scope',[['global','Umumiy platforma (admin tasdig‘i)'],['class','Faqat o‘z guruhim']],'global')}${select('Guruh (guruh uchun nashrda)', 'class_id',[['','Tanlanmagan'],...(data.classes||[]).filter(c=>c.owner===user?.id).map(c=>[c.id,c.title])],'')}<button class="btn">Darsni yuborish</button></form></div>`:''}<div class="stack" style="margin-top:14px">${(data.customLessons||[]).map(l=>`<article class="panel stack"><div class="row between"><h3>${e(l.title)}</h3><span class="pill">${e(l.status==='published'?'Nashr qilingan':l.status==='pending'?'Tasdiq kutilmoqda':'Rad etilgan')}</span></div><details><summary>Mazmunni ochish</summary><p class="docbody">${e(l.body)}</p>${media({mediaType:'youtube',mediaUrl:l.video_url})}</details>${profile?.role==='admin'&&l.status==='pending'?`<div class="row">${btn('Tasdiqlash','approve-lesson','small',`data-id="${l.id}"`)}${btn('Rad etish','reject-lesson','outline small',`data-id="${l.id}"`)}</div>`:''}</article>`).join('')||notice('Qo‘shimcha darslar hali mavjud emas.')}</div>`}
function sharedPage(){let d=data.sharedDoc;return `${section('Ulashilgan hujjat')}${d?`<article class="panel stack"><h2>${e(d.title)}</h2><p class="docbody">${e(d.body)}</p>${btn('PDF / Chop etish','shared-print','outline')}</article>`:notice('Hujjat yuklanmoqda yoki havola mavjud emas.')}`}
let lessonShort=false,focusMode=false,labMode='imlo',labLesson=21,miniIndex=0,miniPick=null,speechInterval=null;
const personKey=k=>(demo?'demo':user?.id||'guest')+'-'+k;
function moduleCard(m,i){let ls=lessons.filter(l=>l.module===i),done=ls.filter(l=>data.progress?.includes(l.id)).length;return `<div class="panel module-card" data-module="${i}"><span class="module-count">0${i}</span><h3>${e(m)}</h3><small>${done}/${ls.length} kichik dars</small><div class="progress"><i style="width:${done/ls.length*100}%"></i></div>${btn('Mavzuni ochish','lesson','secondary',`data-id="${ls.find(l=>!data.progress?.includes(l.id))?.id||ls[0].id}"`)}</div>`}
function mapPage(){return `${section('Bilim xaritasi')}<p class="muted">Ma’ruza bo‘yicha tugallangan darslarni kuzating.</p><div class="grid two module-grid">${modules.map((m,i)=>moduleCard(m,i+1)).join('')}${moduleCardExtra()}</div>${section('Har bir dars holati')}<div class="panel stack">${lessons.map(l=>`<div class="listrow"><span>${data.progress?.includes(l.id)?'✓':'○'} ${e(l.title)}</span>${btn('Ochish','lesson','outline small',`data-id="${l.id}"`)}</div>`).join('')}</div>`}
function moduleCardExtra(){let ls=lessons.filter(l=>!l.module),n=ls.filter(l=>data.progress?.includes(l.id)).length;return `<div class="panel module-card"><h3>Qo‘shimcha darslar</h3><p>${n}/${ls.length}</p><div class="progress"><i style="width:${n/ls.length*100}%"></i></div>${btn('Darslar','goto-lessons','outline')}</div>`}
function mistakesPage(){let qs=bank.filter(q=>get(personKey('mistakes'),[]).includes(q.id));return `${section('Xatolar daftari',`<span class="pill">${qs.length} ta</span>`)}<div class="panel stack"><p>Xato javoblar shu qurilmada saqlanadi. To‘g‘ri ishlaganingizda ro‘yxatdan chiqadi.</p>${btn('Xatolarni takrorlash','retry-mistakes','',qs.length?'':'disabled')}</div><div class="stack">${qs.map(q=>`<div class="panel"><h3>${e(q.question)}</h3><p>${e(q.explanation)}</p></div>`).join('')||notice('Hozircha xato javoblar yo‘q.')}</div>`}
function startSpecial(ids,count){let qs=bank.filter(q=>ids.includes(q.lesson)).sort(()=>Math.random()-.5).slice(0,count);practice={qs,index:0,score:0,pick:null,done:false};go('practice')}
function labsPage(){let modes=[['imlo','Imlo laboratoriyasi'],['speech','Nutq treneri'],['style','Uslub detektori'],['match','Matn va atamalar o‘yini'],['notes','Aqlli konspekt'],['puzzle','Matn konstruktori']];let l=lessons.find(x=>x.id===labLesson)||lessons[0];let q=l.items[miniIndex%5],opts=l.items.map(x=>x[1]);let body='';if(labMode==='match'){body=`<span class="pill">${miniIndex%5+1}/5 · ${e(l.title)}</span><h2>${e(q[0])}</h2><p>To‘g‘ri ta’rifni tanlang.</p>${opts.map((o,i)=>btn(e(o),'mini-answer',miniPick===null?'outline':i===miniIndex%5?'':'outline',`data-id="${i}" ${miniPick!==null?'disabled':''}`)).join('')}${miniPick!==null?notice((miniPick===miniIndex%5?'✓ To‘g‘ri! ':'Qayta eslab qoling: ')+e(q[1]))+btn('Keyingi atama','mini-next'):''}`;}else if(labMode==='puzzle'){body=`<h2>Gaplarni tartiblang</h2><p>Matnning kirish, asosiy qism va xulosasini izchil joylashtiring.</p><div id="puzzle-list" class="stack">${['Shu sababli muntazam o‘qish foydali odatdir.','Kitob o‘qish bilimni kengaytiradi.','O‘qish jarayonida yangi tushunchalar o‘zlashtiriladi.'].map((t,i)=>`<button class="btn outline puzzle-piece" data-piece="${i}">${e(t)}</button>`).join('')}</div><div id="lab-result" class="notice">Gaplarni tartib bo‘yicha bosing.</div>`;}else if(labMode==='speech'){body=`<h2>40 soniyalik taqdimot</h2><p>Kirish: mavzu va maqsad. Asosiy qism: 2–3 fikr va misol. Xulosa: umumlashtirish.</p><textarea id="lab-text" placeholder="Nutq rejangiz..." rows="5"></textarea><div class="speech-clock" id="speech-clock">00:40</div>${btn('Vaqtni boshlash','lab-timer')}`;}else{body=`<h2>${modes.find(x=>x[0]===labMode)[1]}</h2><p>${labMode==='notes'?'Ma’ruza konspektini yozing va saqlang.':labMode==='style'?'Mahalliy kalit so‘zlar orqali taxminiy uslub belgilarini tekshiring.':'Cheklangan mahalliy imlo tekshiruvi: tanish xatolar va tinish belgilaridagi bo‘shliqlar.'}</p><textarea id="lab-text" rows="8" placeholder="Matningizni kiriting...">${labMode==='notes'?e(get(personKey('notes'),'')):''}</textarea>${btn(labMode==='notes'?'Konspektni saqlash':'Tekshirish',labMode==='notes'?'lab-save':'lab-analyze') }<div id="lab-result"></div>${labMode==='notes'?`<div class="stack">${lessons.filter(l=>l.module).map(l=>`<details><summary>${e(l.title)}</summary><p>${e(l.intro)}</p>${l.items.map(x=>`<p><b>${e(x[0])}</b> — ${e(x[1])}</p>`).join('')}</details>`).join('')}</div>`:''}`;}return `${section('Amaliy laboratoriya')}<div class="lab-tabs">${modes.map(([id,t])=>btn(t,'lab-mode',id===labMode?'':'outline',`data-id="${id}"`)).join('')}</div><div class="panel stack lab-body">${body}</div>${section('Yana o‘rganing')}<div class="grid three">${panel('spark','PDF yordamchi','Ma’ruza asosidagi savol-javob va Gemini integratsiyasi.',btn('AI ni ochish','goto-ai','secondary'))}${panel('quiz','Imtihonga tayyorgarlik','Oraliq va yakuniy testlar.',btn('Testlar','goto-practice','secondary'))}${panel('chart','Bilim xaritasi','O‘zlashtirish va xatolar.',btn('Xaritani ochish','goto-map','secondary'))}</div>`}
function analyzeLab(){let t=$('#lab-text').value.trim();if(!t)return toast('Matn kiriting');let lower=t.toLowerCase(),result=[];if(labMode==='imlo'){let pairs=[['xoxish','xohish'],['xar bir','har bir'],['maqsadga muvofiq','maqsadga muvofiq'],['muvaffaqiyat','muvaffaqiyat'],['etibor','e’tibor'],['muommo','muammo'],['xayot','hayot'],['xaqida','haqida'],['xulosa','xulosa'],['noto‘gri','noto‘g‘ri'],['ukamni daftari','ukamning daftari']];for(let [a,b] of pairs)if(a!==b&&lower.includes(a))result.push(a+' → '+b);if(/\s+[,.!?]/.test(t))result.push('Tinish belgisidan oldingi ortiqcha bo‘shliqni olib tashlang.');if(/[,.!?][a-zA-Z]/.test(t))result.push('Tinish belgisidan keyin bo‘shliqni tekshiring.');}else{let sets=[['Ilmiy',['tadqiqot','tahlil','natija','aniqlandi','metod']],['Publitsistik',['aziz','jamiyat','dolzarb','nahotki','islohot']],['Rasmiy',['ariza','buyruq','qaror','tasdiq','mazkur']],['Badiiy',['go‘zal','yurak','shamol','tong','sog‘inch']],['So‘zlashuv',['salom','gap yo‘q','qalesan','zo‘r']]];let ranked=sets.map(([n,ws])=>[n,ws.filter(w=>lower.includes(w))]).sort((a,b)=>b[1].length-a[1].length);result=ranked.filter(x=>x[1].length).map(([n,ws])=>n+': '+ws.join(', '));}$('#lab-result').innerHTML=notice(e(result.join(' · ')||'Aniq belgi topilmadi. Bu to‘liq til tekshiruvi emas.'))+'<small>Qoidaviy taxmin, AI yoki o‘qituvchi bahosi emas.</small>'}
function runSpeechTimer(){clearInterval(speechInterval);let n=40;let tick=()=>{let el=$('#speech-clock');if(!el){clearInterval(speechInterval);return}el.textContent='00:'+String(n).padStart(2,'0');if(n--<=0){clearInterval(speechInterval);toast('Vaqt tugadi. Nutqingizni tahlil qiling.')}};tick();speechInterval=setInterval(tick,1000)}
function lessonPage(){let l=lessons.find(x=>x.id===lessonId)||lessons[0];return `<div class="row">${btn('← Darslar','goto-lessons','outline small')}<span class="pill">${lessons.findIndex(x=>x.id===l.id)+1}/${lessons.length} mavzu</span></div>${section(e(l.title),btn(focusMode?'Fokusdan chiqish':'Fokus rejimi','focus','outline small'))}<div class="panel stack"><div class="row between"><span class="pill">${l.module?`Manba: ${l.module}-ma’ruza · ${l.pages}-sahifalar`:'Qo‘shimcha o‘quv materiali'}</span>${btn(lessonShort?'Batafsil dars':'Qisqa konspekt','lesson-view','outline small')}</div><p>${e(l.intro)}</p>${lessonShort?`<ul class="note-list">${l.items.map(([t,d])=>`<li><b>${e(t)}</b> — ${e(d)}</li>`).join('')}</ul>`:l.items.map(([t,d,x],i)=>`<div class="listrow" style="display:block"><div class="label">${i+1} · TUSHUNCHA</div><h3 style="margin-top:7px">${e(t)}</h3><p>${e(d)}.</p><div class="notice"><strong>Misol:</strong> ${e(x)}</div></div>`).join('')}<h3>Amaliy mashq</h3><p>${e(l.task||"Ushbu mavzudagi tushunchalardan foydalanib, 5–7 gapdan iborat akademik matn yozing.")}</p><div class="row">${btn(data.progress?.includes(l.id)?'✓ Tugallangan':'Darsni tugatish','complete','',`data-id="${l.id}" ${data.progress?.includes(l.id)?'disabled':''}`)}${btn('25 ta mashqni ishlash','practice-lesson','secondary',`data-id="${l.id}"`)}</div></div><div class="grid two lesson-actions">${panel('bolt','Kartochkalar','Shu mavzudagi 5 ta tushunchani takrorlang.',btn('Kartochkalarni ochish','lesson-cards','secondary',`data-id="${l.id}"`))}${panel('game','Mini o‘yin','Atama va ta’rifni moslashtiring.',btn('O‘yinni boshlash','lesson-mini','secondary',`data-id="${l.id}"`))}</div>${section('Muhokama')}<div class="panel stack">${(data.comments||[]).map(c=>`<div class="listrow"><div><small>${e(new Date(c.created_at).toLocaleString('uz-UZ'))}</small><p>${e(c.body)}</p></div>${(c.author===user?.id||profile?.role==='admin')?btn('O‘chirish','delete-comment','outline small',`data-id="${c.id}"`):''}</div>`).join('')||'<p class="muted">Hozircha izohlar yo‘q.</p>'}${demo?notice('Izohlar faqat ulangan akkauntda ishlaydi.'): `<form class="stack" data-form="comment">${area('Fikringiz','body','','required maxlength="1500"')}<button class="btn">Izoh yuborish</button></form>`}</div>`}
function startPractice(id=0){let qs=id?bank.filter(q=>q.lesson===id):[...bank].sort(()=>Math.random()-.5).slice(0,20);practice={qs,index:0,score:0,pick:null,done:false};go('practice')}
function practicePage(){if(!practice)return `${section('Mustaqil testlar',`<span class="pill">${bank.length} savol</span>`)}<div class="panel stack"><h3>Bilimingizni sinang</h3><p>Har bir mavzu uchun 25 ta savol yoki aralash 20 ta savolni ishlang.</p>${btn('Aralash testni boshlash','practice-all')}<div class="row">${btn('Oraliq nazorat · 20 savol','exam-mid','secondary')}${btn('Yakuniy nazorat · 30 savol','exam-final','secondary')}${btn('Xatolar daftari','goto-mistakes','outline')}</div></div><div class="grid three" style="margin-top:16px">${lessons.map(l=>`<div class="panel stack"><span class="label">Mavzu ${l.id}</span><h3>${e(l.title)}</h3>${btn('25 ta savol','practice-lesson','secondary',`data-id="${l.id}"`)}</div>`).join('')}</div>`;let p=practice;if(p.done)return `${section('Test natijasi')}<div class="panel stack" style="text-align:center"><div class="ico" style="margin:auto">${icon('trophy')}</div><h1>${p.score}/${p.qs.length}</h1><p>To‘g‘ri javoblar · ${Math.round(p.score/p.qs.length*100)}%</p>${btn('Yangi test','practice-reset')}</div>`;let q=p.qs[p.index];return `${section(`Savol ${p.index+1}/${p.qs.length}`,btn('Chiqish','practice-reset','outline small'))}<div class="panel stack"><div class="progress"><i style="width:${(p.index+1)/p.qs.length*100}%"></i></div><h2>${e(q.question)}</h2>${q.options.map((o,i)=>`<button class="btn ${p.pick!==null&&q.answer.includes(i)?'': 'outline'}" style="text-align:left;justify-content:flex-start;${p.pick===i&&!q.answer.includes(i)?'border-color:#d83b58;color:#d83b58':''}" data-act="practice-answer" data-id="${i}" ${p.pick!==null?'disabled':''}>${String.fromCharCode(65+i)}. ${e(o)}</button>`).join('')}${p.pick!==null?notice((q.answer.includes(p.pick)?'✓ To‘g‘ri! ':'Noto‘g‘ri. ')+'<br><b>To‘g‘ri javob:</b> '+e(q.answer.map(i=>q.options[i]).join(', '))+'<br>'+e(q.explanation))+btn('Keyingi savol →','practice-next'):''}</div>`}
function studio(){return `${section('Test yaratish')}<div class="grid two"><div class="panel stack"><h3>Tayyor savollar bazasi</h3><form class="stack" data-form="bank-add">${select('Mavzu','lesson',lessons.map(l=>[l.id,l.title]),1)}${field('Savollar soni','count','number',10,'min="1" max="25" required')}<button class="btn">Savollarni qo‘shish</button></form><small>1000 ta mashq savoli · mavzu bo‘yicha tanlash.</small></div><div class="panel stack"><h3>Yangi savol</h3><form class="stack" data-form="question-add">${area('Savol','question','','required maxlength="1000"')}${select('Turi','type',[['choice','Bitta javob'],['multiple','Bir nechta javob'],['boolean','To‘g‘ri / noto‘g‘ri']], 'choice')}${area('Variantlar (har biri alohida qatorda)','options','','required placeholder="Birinchi variant\nIkkinchi variant"')}${field('To‘g‘ri javob raqamlari (1 yoki 1,3)','answer','text','1','required')}${field('Vaqt (soniya)','time','number','30','min="5" max="120" required')}${field('Izoh','explanation')}${select('Media turi','mediaType',[['','Yo‘q'],['image','Rasm URL'],['audio','Audio URL'],['youtube','YouTube URL']],'')}${field('Media havolasi','mediaUrl','url')}<button class="btn">Savol qo‘shish</button></form></div></div>${section(`Test tarkibi (${builder.length})`,btn('Yangi test','clear-builder','outline small'))}<div class="panel stack">${builder.map((q,i)=>`<div class="listrow"><div><strong>${i+1}. ${e(q.question)}</strong><br><small>${q.options.map((o,j)=>`${q.answer.includes(j)?'✓ ':''}${e(o)}`).join(' · ')}</small></div>${btn('×','remove-q','outline small',`data-id="${i}" aria-label="Savolni o‘chirish"`)}</div>`).join('')||'<p class="muted">Savollar qo‘shing.</p>'}<form class="stack" data-form="quiz-save">${field('Test nomi','title','text',editingQuiz?.title||'','required maxlength="150"')}${check('Boshqa foydalanuvchilar ham ishlata olsin','public',!!editingQuiz?.is_public)}${check('Keyingi savol avtomatik ochilsin','auto')}${check('Kech qo‘shilishga ruxsat','late')}${check('Savol faqat proyektorda ko‘rinsin','projector')}${check('Imtihon rejimi (tezlik bonussiz)','exam')}<div class="row"><button class="btn" name="action" value="save">Testni saqlash</button><button class="btn secondary" name="action" value="live">Jonli o‘yin ochish</button></div></form></div>${section('Saqlangan testlar')}<div class="panel">${(data.quizzes||[]).map(q=>`<div class="listrow"><div><strong>${e(q.title)}</strong><br><small>${q.questions.length} savol · ${q.is_public?'Ochiq':'Shaxsiy'}</small></div><div class="row">${btn(demo||q.owner===user?.id?'Tahrirlash':'Nusxa olish','load-quiz','outline small',`data-id="${q.id}"`)}${demo||q.owner===user?.id?btn('O‘chirish','delete-quiz','outline small',`data-id="${q.id}"`):''}</div></div>`).join('')||'<p class="muted">Saqlangan testlar yo‘q.</p>'}</div>`}
function livePage(){return `${section('ILMORA Live')}<div class="hero"><div><div class="label">REAL VAQTDA BILIM BELLASHUVI</div><h1>Birga o‘ynang. Birga o‘rganing.</h1><p>PIN orqali qo‘shiling yoki o‘z testingiz bilan xona oching.</p>${btn('O‘yinga qo‘shilish','join')}</div><div class="hero-art">${heroArt}</div></div>${section('O‘yin yaratish')}<div class="grid two">${panel('game','Tayyor test','10 ta aralash savoldan klassik o‘yin.',btn('Tezkor xona yaratish','quick-host'))}${panel('quiz','Imtihon rejimi','10 ta savol, tezlik bonusisiz. Alohida ko‘rinish.',btn('Imtihon xonasi','exam-host','secondary'))}${panel('quiz','O‘z testingiz','Savollar, vaqt va o‘yin sozlamalarini tanlang.',btn('Test studiyasi','goto-studio','secondary'))}</div>${section('O‘yinlar tarixi')}<div class="panel">${(data.reports||[]).map(r=>`<div class="listrow"><div><strong>${e(r.title)}</strong><br><small>${r.count} ishtirokchi · ${e(r.phase)} · ${e(new Date(r.date).toLocaleDateString('uz-UZ'))}</small></div>${btn('Ochish','resume-host','outline small',`data-id="${r.id}"`)}</div>`).join('')||'<p class="muted">O‘yinlar hali yo‘q.</p>'}</div>`}
function joinPage(){return `<div class="game ${s.settings?.exam?'game-exam':'game-classic'} phase-${e(s.phase)}"><div class="game-inner"><header class="game-head">${logo()}${btn('← Qaytish','home','outline')}</header><div class="gamecard" style="max-width:480px;margin:55px auto"><span class="pill" style="background:#fff2;color:white">ILMORA LIVE</span><h1>O‘yinga qo‘shiling</h1><p class="muted">O‘qituvchi yoki do‘stingiz bergan PIN-kodni kiriting.</p><form class="stack" data-form="join" style="margin-top:25px"><input class="control" name="pin" value="${e(new URLSearchParams(location.search).get('pin')||'')}" placeholder="6 xonali PIN" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required aria-label="PIN-kod" style="text-align:center;font-size:25px;letter-spacing:5px"><input class="control" name="name" placeholder="Ismingiz yoki taxallusingiz" maxlength="32" required aria-label="Ism"><button class="btn secondary">O‘yinga kirish →</button></form>${!configured?`<p class="muted">Haqiqiy jonli o‘yin uchun Supabase ulanishi kerak.</p>${btn('Bir kishilik demo test','demo-game','outline')}`:''}</div></div></div>`}
const safeURL=s=>{try{let u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
function media(q){let u=safeURL(q?.mediaUrl);if(!u)return '';if(q.mediaType==='image')return `<img class="media" src="${e(u)}" alt="Savol rasmi" referrerpolicy="no-referrer">`;if(q.mediaType==='audio')return `<audio controls src="${e(u)}"></audio>`;if(q.mediaType==='youtube'){let id='';try{let t=new URL(u);if(t.hostname==='youtu.be')id=t.pathname.slice(1);else if(['www.youtube.com','youtube.com','m.youtube.com'].includes(t.hostname))id=t.searchParams.get('v')||''}catch{}if(/^[\w-]{11}$/.test(id))return `<iframe title="Savol videosi" style="width:100%;max-width:480px;aspect-ratio:16/9;border:0" src="https://www.youtube-nocookie.com/embed/${id}" allowfullscreen></iframe>`}return ''}
function gamePage(){if(!liveState)return `<div class="game"><div class="game-inner">${logo()}<div class="gamecard"><h2>Xonaga ulanmoqda…</h2>${btn('Chiqish','leave-live','outline')}</div></div></div>`;const s=liveState, q=s.question, host=s.host;let b='';let names=s.players||[];if(s.phase==='lobby'){b=`<div class="gamecard"><span class="muted">O‘YIN PIN-KODI</span><div class="pin">${e(s.pin)}</div><h2>${e(s.title)}</h2><p>${s.count}/50 ishtirokchi</p>${host?`<div class="row" style="justify-content:center;margin:15px 0">${btn('Havolani nusxalash','copy-join','outline')}${btn('O‘yinni boshlash','live-start','secondary',s.count?'':'disabled')}</div>`:'<p>O‘qituvchi boshlashini kuting…</p>'}<div class="players">${names.map(p=>`<span class="player">${e(p.name)} ${host?`<button class="btn outline small" data-act="kick" data-id="${p.id}">×</button>`:''}</span>`).join('')}</div></div>`}else if(s.phase==='question'){b=`<div class="row between"><span>Savol ${s.index+1}/${s.total}</span><span id="seconds" style="font-size:25px;font-weight:800">—</span><span>${s.answered}/${s.count} javob</span></div><div class="progress"><i id="timebar" style="width:100%"></i></div><div class="gamecard"><h1>${e(q.question||'Savolni proyektorda ko‘ring')}</h1>${media(q)}</div><div class="answers">${q.options.map((o,i)=>`<button class="answer ${selected.includes(i)?'selected':''}" data-act="live-pick" data-id="${i}" ${host||s.mine?.submitted?'disabled':''}><span style="font-size:25px">${['▲','◆','●','■','⬟','★'][i]}</span>${e(o)}</button>`).join('')}</div>${host?btn('Javoblarni ochish','live-reveal','secondary'):s.mine?.submitted?'<div class="gamecard">✓ Javob qabul qilindi. Natijani kuting.</div>':q.type==='multiple'?btn('Javoblarni yuborish','live-submit','secondary block'):''}`}
else if(s.phase==='reveal'){b=`<div class="gamecard"><span class="pill" style="background:#fff2;color:white">NATIJA · ${s.index+1}/${s.total}</span><h1>${host?'To‘g‘ri javob':s.mine?.correct?'✓ To‘g‘ri!':s.mine?.submitted?'Noto‘g‘ri javob':'Javob berilmadi'}</h1>${!host&&s.mine?.submitted?`<h2>+${s.mine.points} ball</h2>`:''}<p>${e(q.question)}</p><div class="answers">${q.options.map((o,i)=>`<div class="answer ${q.answer?.includes(i)?'correct':'wrong'}">${q.answer?.includes(i)?'✓':'•'} ${e(o)}</div>`).join('')}</div><p>${e(q.explanation||'')}</p>${host?btn('Keyingi savol →','live-next','secondary'):'<p>Keyingi savolni kuting…</p>'}</div>${host?`<div class="gamecard"><h3>Javoblar taqsimoti</h3>${(s.stats||[]).map(a=>`<p>${a.choice.map(i=>e(q.options[i])).join(', ')} — ${a.count} ta</p>`).join('')}</div>`:''}${rank(names)}`}
else {let top=names.slice(0,3);b=`<div class="gamecard"><div class="label" style="color:#f5ce50">MUSOBAQA YAKUNLANDI</div><h1>G‘oliblar!</h1><div class="podium">${[top[1],top[0],top[2]].map((p,i)=>p?`<div><h2>${[2,1,3][i]}-o‘rin</h2><strong>${e(p.name)}</strong><p>${p.score} ball</p></div>`:'<div></div>').join('')}</div>${host?btn('CSV hisobot','report-download','secondary'):''}${btn('Bosh sahifaga','leave-live','outline')}</div>${rank(names)}`}
return `<div class="game ${s.settings?.exam?'game-exam':'game-classic'} phase-${e(s.phase)}"><div class="game-inner"><header class="game-head">${logo()}<div class="row">${host&&s.phase!=='finished'?btn('O‘yinni yakunlash','live-finish','outline small'):''}${btn('Chiqish','leave-live','outline small')}</div></header>${b}</div></div>`}
function rank(names){return `<div class="gamecard"><h2>Reyting</h2>${names.map((p,i)=>`<div class="listrow" style="border-color:#fff2;text-align:left"><span>${i+1}. ${e(p.name)}</span><strong>${p.score} ball</strong></div>`).join('')}</div>`}
function textStats(s){let words=s.trim()?s.trim().split(/\s+/):[];let f={};for(let w of words){w=w.toLocaleLowerCase().replace(/[^\p{L}\p{N}‘’ʻʼ'-]/gu,'');if(w.length>4)f[w]=(f[w]||0)+1}return {words:words.length,chars:s.length,sentences:s.split(/[.!?]+/).filter(x=>x.trim()).length,paras:s.split(/\n\s*\n/).filter(x=>x.trim()).length,repeat:Object.entries(f).filter(x=>x[1]>2).sort((a,b)=>b[1]-a[1]).slice(0,8)}}
function statHTML(s){let a=textStats(s);return `<div class="grid two">${[['So‘z',a.words],['Belgi',a.chars],['Gap',a.sentences],['Abzats',a.paras]].map(([t,v])=>`<div class="panel stat" style="padding:12px"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div><p class="muted">Takrorlangan so‘zlar: ${a.repeat.map(([w,n])=>`${e(w)} (${n})`).join(', ')||'—'}</p><div class="notice">Matnni dalillar bilan asoslang. Har bir abzatsda bitta asosiy fikrni rivojlantiring. Bu oddiy statistik tahlil, grammatik yoki plagiat tekshiruvi emas.</div>`}
const templates={esse:'Kirish\n\nMavzuning dolzarbligi va tezis fikri.\n\nAsosiy qism\n\n1-dalil va misol.\n\n2-dalil va misol.\n\nXulosa\n\nAsosiy natija.',referat:'Titul varaq\n\nMundarija\n\nKirish\n\n1-bob\n\n2-bob\n\nXulosa\n\nFoydalanilgan adabiyotlar',maqola:'Sarlavha\n\nAnnotatsiya\n\nKalit so‘zlar\n\nKirish\n\nMetodologiya\n\nNatijalar\n\nMuhokama\n\nXulosa\n\nAdabiyotlar',annotatsiya:'Asar yoki maqola nomi\n\nMaqsad\n\nAsosiy mazmun\n\nNatija'};
function writing(){if(!doc)doc={id:null,title:'Yangi hujjat',body:''};return `${section('Writing Studio',btn('Yangi hujjat','doc-new','outline small'))}<div class="split"><div class="panel stack"><input class="control" id="doc-title" value="${e(doc.title)}" maxlength="200" aria-label="Hujjat nomi"><div class="row">${Object.keys(templates).map(t=>btn(t,'template','secondary small',`data-id="${t}"`)).join('')}</div><textarea class="control editor" id="doc-body" placeholder="Akademik matningizni yozishni boshlang…">${e(doc.body)}</textarea><div class="row">${btn('Saqlash','doc-save')}${btn('PDF / Chop etish','doc-print','outline')}${btn('Word (.docx)','doc-word','outline')}${btn('AI tahlil','doc-ai','secondary')}${!demo&&doc.id?btn('Havola yaratish','doc-share','outline')+btn('Havolani bekor qilish','doc-unshare','outline small'):''}</div><small>Matn avtomatik mahalliy qoralamaga saqlanadi. Bulutga saqlash uchun «Saqlash» tugmasini bosing.</small></div><div class="panel stack"><h3>Jonli matn tahlili</h3><div id="text-stats">${statHTML(doc.body)}</div></div></div>${section('Hujjatlarim')}<div class="panel">${(data.docs||[]).map(d=>`<div class="listrow"><strong>${e(d.title)}</strong><div class="row">${btn('Ochish','doc-open','outline small',`data-id="${d.id}"`)}${btn('O‘chirish','doc-delete','outline small',`data-id="${d.id}"`)}</div></div>`).join('')||'<p class="muted">Hujjatlar yo‘q.</p>'}</div>`}
function aiPage(){let tool=tools.find(x=>x[0]===aiTool)||tools[0];return `${section('ILMORA AI',btn('Yangi suhbat','ai-new','outline small'))}<div class="split" style="grid-template-columns:260px 1fr"><div class="panel stack"><h3>AI vositalari</h3>${tools.map(([id,t,d])=>`<button class="nav ${id===aiTool?'active':''}" data-act="ai-tool" data-id="${id}">${icon('spark')}${e(t)}</button>`).join('')}<h3>Suhbatlar tarixi</h3>${(data.chats||[]).slice(0,20).map(c=>`<button class="nav" data-act="chat-open" data-id="${c.id}">${e(c.title.slice(0,35))}</button>`).join('')||'<small>Hali suhbat yo‘q.</small>'}</div><div class="panel stack"><div class="row"><div class="ico" style="margin:0">${icon('spark')}</div><div><h2>${e(tool[1])}</h2><small>${e(tool[2])}</small></div></div>${notice('AI faqat akademik yozuvga yordam beradi. Javoblar xato bo‘lishi mumkin. Baho o‘qituvchi tomonidan qo‘yiladi. Bepul AI kvotasi cheklangan.')}${demo?notice('Demo: Gemini ulanmagan. Mahalliy tavsiyalar ishlaydi.',true):''}<div class="messages" id="messages">${messages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><strong>${m.role==='user'?'Siz':'ILMORA'}</strong><br>${e(m.text)}</div>`).join('')||'<div class="empty">Savolingizni yozing yoki vosita tanlang.</div>'}</div>${aiTool==='quiz'&&messages.at(-1)?.role==='assistant'?btn('AI javobini test studiyasiga import qilish','ai-import','secondary'):''}<form class="stack" data-form="ai">${data.assignments?.length?select('Topshiriq konteksti (ixtiyoriy)','assignment',[['','Umumiy akademik yordam'],...data.assignments.map(a=>[a.id,a.title])],aiAssignment):''}${area('Xabar','prompt',data.aiDraft||'','required maxlength="12000" placeholder="Masalan: Ilmiy uslubni misollar bilan tushuntir..."')}${aiTool==='pdf'?'<label class="field">PDF (2 MB gacha)<input type="file" name="pdf" accept="application/pdf"></label>':''}${check('AI xizmatiga matn yuborilishiga roziman; maxfiy yoki shaxsiy ma’lumot yubormayman.','consent')}<button class="btn" ${busyAI?'disabled':''}>${busyAI?'Javob tayyorlanmoqda…':'Yuborish →'}</button></form></div></div>`}
function library(){return `${section('Kutubxona va shablonlar')}<div class="grid two">${Object.entries(templates).map(([k,v])=>`<div class="panel stack"><div class="ico">${icon('file')}</div><h3>${e(k.charAt(0).toUpperCase()+k.slice(1))} shabloni</h3><p class="muted">Akademik tuzilma namunasi.</p>${btn('Muharrirda ochish','library-template','secondary',`data-id="${k}"`)}</div>`).join('')}</div>${section('Ochiq o‘quv resurslari')}<div class="panel stack"><a href="https://owl.purdue.edu/" target="_blank" rel="noopener noreferrer">Purdue OWL — akademik yozuv bo‘yicha qo‘llanma (inglizcha)</a><a href="https://apastyle.apa.org/" target="_blank" rel="noopener noreferrer">APA Style — rasmiy iqtibos qo‘llanmasi (inglizcha)</a><a href="https://style.mla.org/" target="_blank" rel="noopener noreferrer">MLA Style Center (inglizcha)</a><small>6 ta ma’ruza asosidagi konspektlar Darslar bo‘limida. Qo‘shimcha video materiallar hali kiritilmagan.</small></div>`}
function citation(){return `${section('Iqtibos generatori')}<div class="panel stack"><p>Kitob uchun soddalashtirilgan APA 7 yoki MLA 9 bibliografik yozuvi. Muallif familiyasi va initsiallarini kerakli tartibda kiriting.</p><form class="stack" data-form="citation">${select('Standart','style',[['apa','APA 7'],['mla','MLA 9']],'apa')}${field('Muallif','author','text','','required placeholder="Karimov, A."')}${field('Kitob nomi','title','text','','required')}${field('Nashr yili','year','number','','required min="1000" max="2100"')}${field('Nashriyot','publisher','text','','required')}<button class="btn">Iqtibos yaratish</button></form><div id="citation-output"></div></div>`}
function cards(){let l=lessons[Math.floor(cardIndex/5)%lessons.length],c=l.items[cardIndex%5];return `${section('Akademik kartochkalar')}<div class="panel stack" style="text-align:center;min-height:300px;justify-content:center"><span class="pill" style="justify-self:center">${cardIndex+1}/${lessons.length*5} · ${e(l.title)}</span><h1>${e(cardFlip?c[1]:c[0])}</h1><p class="muted">${cardFlip?e(c[2]):'Ta’rifni eslashga harakat qiling.'}</p>${btn(cardFlip?'Atamani ko‘rish':'Ta’rifni ochish','card-flip','secondary')}<div class="row" style="justify-content:center">${btn('← Oldingi','card-prev','outline')}${btn('Keyingi →','card-next','outline')}</div></div>`}
function classes(){return `${section('O‘quv guruhlari')}<div class="grid two">${isStaff()?`<div class="panel stack"><h3>Guruh yaratish</h3><form class="stack" data-form="class-create">${field('Guruh nomi','title','text','','required maxlength="120"')}<button class="btn">Yaratish</button></form></div>`:''}<div class="panel stack"><h3>Guruhga qo‘shilish</h3><form class="stack" data-form="class-join">${field('Guruh kodi','code','text','','required')}<button class="btn">Qo‘shilish</button></form></div></div>${section('Guruhlarim')}<div class="grid two">${(data.classes||[]).map(c=>`<div class="panel stack"><h3>${e(c.title)}</h3><p>Kod: <strong>${e(c.code)}</strong></p>${c.owner===user?.id?`<form class="stack" data-form="class-add" data-id="${c.id}">${field('Talaba emaili','email','email','','required')}<button class="btn secondary">A’zo qo‘shish</button></form>`:''}</div>`).join('')||notice('Hali guruh yo‘q.')}</div>`}
function assignments(){return `${section('Topshiriqlar')}${isStaff()?`<div class="panel stack"><h3>Topshiriq yaratish</h3><form class="stack" data-form="assignment-create">${select('Guruh','class_id',(data.classes||[]).filter(c=>c.owner===user?.id).map(c=>[c.id,c.title]),'')}${field('Nomi','title','text','','required')}${area('Tavsif','description','','required')}${field('Muddat','due','datetime-local')}${select('Baholash','scale',[[100,'100 ballik'],[5,'5 ballik']],100)}${select('AI ruxsati','policy',[['off','AI o‘chirilgan'],['guide','Faqat tavsiya'],['full','Namunaviy to‘liq matn']],'guide')}<button class="btn">Topshiriq berish</button></form></div>`:''}${section('Mavjud topshiriqlar')}<div class="stack">${(data.assignments||[]).map(a=>{let own=a.owner===user?.id;let subs=(data.submissions||[]).filter(s=>s.assignment_id===a.id);return `<div class="panel stack"><div class="row between"><h3>${e(a.title)}</h3><span class="pill">${a.scale} ball</span></div><p>${e(a.description)}</p><small>Muddat: ${a.due_at?e(new Date(a.due_at).toLocaleString('uz-UZ')):'Cheklanmagan'} · AI: ${e(a.ai_policy)}</small>${own?subs.map(s=>`<div class="notice"><p class="docbody">${e(s.body)}</p><form class="stack" data-form="grade" data-id="${s.id}">${field('Baho','grade','number',s.grade??'','required min="0" max="'+a.scale+'" step="0.1"')}${area('Izoh','comment',s.comment||'')}<button class="btn small">Baholash</button></form></div>`).join('')||'<small>Topshirilgan ish yo‘q.</small>':subs.length?notice(`Topshirildi. Baho: ${subs[0].grade??'kutilmoqda'}<br>${e(subs[0].comment||'')}`):`<form class="stack" data-form="submit-assignment" data-id="${a.id}">${area('Yozma ishingiz','body','','required maxlength="100000"')}<button class="btn">Topshirish</button></form>`}</div>`}).join('')||notice('Topshiriqlar hali yo‘q.')}</div>`}
function leader(){return `${section('Talabalar reytingi')}<div class="panel"><p class="muted">Faqat taxallus va XP ballari ko‘rsatiladi.</p>${(data.leader||[]).map((a,i)=>`<div class="listrow"><div class="row"><span class="pill">#${i+1}</span><span class="avatar">${e(a.nickname.slice(0,2).toUpperCase())}</span><strong>${e(a.nickname)}</strong></div><strong>${a.xp} XP</strong></div>`).join('')||'<p class="muted">Natijalar yo‘q.</p>'}</div>`}
function stats(){let p=data.progress?.length||0;return `${section('O‘quv statistikasi')}<div class="grid three">${[['Darslar',p+'/'+lessons.length],['XP',profile?.xp||0],['Daraja',Math.floor((profile?.xp||0)/200)+1]].map(([t,v])=>`<div class="panel stat"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div>${section('Kursni tugatish')}<div class="panel stack"><div class="progress"><i style="width:${p/lessons.length*100}%"></i></div><p>${p} ta mavzu tugallangan.</p>${btn('Sertifikatni chop etish','certificate','',p===lessons.length?'':'disabled')}<small>ILMORA ichki o‘quv sertifikati, rasmiy davlat diplomi emas.</small></div>`}
function profilePage(){return `${section('Shaxsiy profil')}<div class="panel stack"><div class="row"><span class="avatar">${e(profile?.name?.slice(0,2))}</span><div><h3>${e(profile?.name)}</h3><small>${e(user?.email||'Mahalliy demo')}</small></div></div><form class="stack" data-form="profile">${field('Ism','name','text',profile?.name,'required maxlength="80"')}${field('Taxallus','nickname','text',profile?.nickname,'required maxlength="40"')}<button class="btn">Saqlash</button></form>${profile?.role==='student'?`<h3>O‘qituvchi bo‘lish</h3><p>Admin ism va emailingiz asosida arizani ko‘rib chiqadi.</p>${data.request?.status?notice('Ariza: '+e(data.request.status)):''}${btn('Ariza yuborish','teacher-request','secondary',data.request?.status==='pending'?'disabled':'')}`:''}${btn('Akkauntdan chiqish','logout','outline')}</div>`}
function admin(){if(profile?.role!=='admin')return notice('Ruxsat yo‘q.');return `${section('Administrator paneli')}<div class="grid three"><div class="panel stat"><small>Foydalanuvchilar</small><strong>${data.users?.length||0}</strong></div><div class="panel stat"><small>Kutilayotgan arizalar</small><strong>${(data.requests||[]).filter(r=>r.status==='pending').length}</strong></div><div class="panel stat"><small>Fikr-mulohazalar</small><strong>${data.feedback?.length||0}</strong></div></div>${section('O‘qituvchilik arizalari')}<div class="panel">${(data.requests||[]).map(r=>`<div class="listrow"><div><strong>${e(r.name)}</strong><br><small>${e(r.email)} · ${e(r.status)}</small></div>${r.status==='pending'?`<div class="row">${btn('Tasdiqlash','approve','small',`data-id="${r.id}"`)}${btn('Rad etish','reject','outline small',`data-id="${r.id}"`)}</div>`:''}</div>`).join('')||'<p>Arizalar yo‘q.</p>'}</div>${section('Foydalanuvchilar')}<div class="panel">${(data.users||[]).map(u=>`<div class="listrow"><strong>${e(u.name)}</strong><span class="pill">${e(u.role)}</span></div>`).join('')}</div>${section('Fikr-mulohazalar')}<div class="panel">${(data.feedback||[]).map(f=>`<div class="listrow"><p>${e(f.body)}</p><small>${e(new Date(f.created_at).toLocaleDateString('uz-UZ'))}</small></div>`).join('')||'<p>Hali xabar yo‘q.</p>'}</div>`}
function notifications(){return `${section('Bildirishnomalar')}<div class="panel">${(data.notifications||[]).map(n=>`<div class="listrow"><p>${e(n.body)} ${n.read_at?'':'<span class="pill">Yangi</span>'}</p>${n.read_at?'':btn('O‘qildi','notice-read','outline small',`data-id="${n.id}"`)}</div>`).join('')||'<p class="muted">Yangi bildirishnoma yo‘q.</p>'}</div>`}
function feedback(){return `${section('Fikr-mulohaza')}<div class="panel stack"><p>Taklifingiz yoki aniqlagan xatoni yozing.</p><form class="stack" data-form="feedback">${area('Xabar','body','','required maxlength="3000"')}<button class="btn">Yuborish</button></form></div>`}
async function loadData(r){if(demo){data.progress=get('demo-progress',[]);data.docs=get('demo-docs',[]);data.quizzes=get('demo-quizzes',[]);data.chats=get('demo-chats',[]);data.leader=[{nickname:profile.nickname,xp:profile.xp}];return}if(!user||!sb)return;const tasks=[];let add=(k,p)=>tasks.push(p.then(v=>data[k]=v).catch(err=>{console.error(k,err);toast('Ma’lumotni yuklashda xato: '+err.message)}));if(['home','lessons','lesson','stats','map'].includes(r))add('progress',query('progress',q=>q.select('lesson_id')).then(a=>a.map(x=>x.lesson_id)));if(r==='lessons'&&!demo){add('customLessons',query('custom_lessons',q=>q.select('*').order('created_at',{ascending:false})));if(isStaff())add('classes',query('classes',q=>q.select('*')))}if(r==='shared'){data.sharedDoc=null;add('sharedDoc',api('read_shared_document',{p_token:location.hash.split('/')[1]}))}if(r==='lesson')add('comments',query('lesson_comments',q=>q.select('*').eq('lesson_id',lessonId).order('created_at',{ascending:false})));if(r==='writing')add('docs',query('documents',q=>q.select('*').order('updated_at',{ascending:false})));if(r==='studio')add('quizzes',query('quizzes',q=>q.select('*').order('created_at',{ascending:false})));if(r==='live')add('reports',api('live_reports'));if(r==='ai')add('chats',query('ai_conversations',q=>q.select('*').order('updated_at',{ascending:false})));if(['classes','assignments'].includes(r))add('classes',query('classes',q=>q.select('*').order('created_at',{ascending:false})));if(['assignments','ai'].includes(r))add('assignments',query('assignments',q=>q.select('*').order('created_at',{ascending:false})));if(r==='assignments')add('submissions',query('submissions',q=>q.select('*')));if(r==='leader')add('leader',api('leaderboard'));if(r==='profile')add('request',query('teacher_requests',q=>q.select('*').eq('user_id',user.id).maybeSingle()));if(r==='notifications')add('notifications',query('notifications',q=>q.select('*').order('created_at',{ascending:false})));if(r==='admin'&&profile.role==='admin'){add('users',query('profiles',q=>q.select('*').limit(200)));add('requests',query('teacher_requests',q=>q.select('*').order('created_at',{ascending:false})));add('feedback',query('feedback',q=>q.select('*').order('created_at',{ascending:false})))}await Promise.all(tasks)}
function render(){let fn={landing,auth:authPage,home,lessons:lessonList,lesson:lessonPage,practice:practicePage,studio,live:livePage,join:joinPage,game:gamePage,writing,ai:aiPage,library,citation,cards,classes,assignments,leader,stats,profile:profilePage,admin,notifications,feedback,shared:sharedPage,labs:labsPage,map:mapPage,mistakes:mistakesPage}[route]||home;let html=fn();document.body.dataset.route=route;document.body.classList.toggle('focus-mode',route==='lesson'&&focusMode);root.innerHTML=['landing','auth','join','game'].includes(route)?html:shell(html);if(route==='game')tick();if(route==='ai'){let el=$('#messages');if(el)el.scrollTop=el.scrollHeight}}
async function navigate(){let token=++renderKey;let next=location.hash.slice(1)|| (user||demo?'home':'landing');if(next.startsWith('lesson/')){lessonId=Math.min(lessons.length,Math.max(1,Number(next.split('/')[1])||1));next='lesson'}if(next.startsWith('shared/'))next='shared';if(!Object.keys(pageNames).includes(next))next='landing';if(next==='home'&&!user&&!demo)next='landing';if(!user&&!demo&&!['landing','auth','join','game'].includes(next)){if(next==='shared')sessionStorage.setItem('ilmora-return',location.hash.slice(1));next='auth';authMode='login'}if(next==='game'&&!live){let saved=get('live',null);if(saved&&(!saved.host||user))live=saved;else next='join'}if(route==='game'&&next!=='game')stopLive();route=next;if(next!=='lesson')focusMode=false;render();await loadData(next);if(token!==renderKey)return;render();if(next==='game'&&live&&!live.demo)connectLive();window.scrollTo(0,0)}
async function refresh(){await loadData(route);render()}
async function refreshProfile(){if(user)profile=await query('profiles',q=>q.select('*').eq('id',user.id).single())}
function startDemo(){demo=true;profile=get('demo-profile',{name:'Talaba',nickname:'Demo-talaba',role:'student',xp:0});data={};doc=get('demo-draft',null);go('home')}
async function ensureAuth(){if(!sb)throw Error('Supabase sozlanmagan. Avval README bo‘yicha ulang.');if(!user)throw Error('Avval tizimga kiring.');}
async function hostGame(title,qs,settings){if(demo){live={demo:true,host:true};let q=qs.slice(0,5);practice={qs:q,index:0,score:0,pick:null,done:false};toast('Demo — bir kishilik test. Haqiqiy xona uchun Supabase kerak.');go('practice');return}await ensureAuth();let r=await api('live_create',{p_title:title,p_questions:qs,p_settings:settings});live={id:r.id,host:true,pin:r.pin};liveState=null;selected=[];save('live',live);go('game')}
async function pullLive(){if(!live||live.demo||liveRequest||route!=='game')return;liveRequest=true;try{let id=live.id;let s=await api('live_state',{p_room:id,p_token:live.token||null});if(route!=='game'||live?.id!==id)return;let prev=liveState;if(!prev||s.index!==prev.index||s.phase!==prev.phase)selected=[];let changed=!prev||JSON.stringify({...prev,serverTime:undefined,offset:undefined})!==JSON.stringify({...s,serverTime:undefined,offset:undefined});liveState=s;liveState.offset=Date.parse(s.serverTime)-Date.now();if(changed)render();else tick();if(s.phase==='finished')stopLive()}catch(err){toast('O‘yin ulanishi: '+err.message)}finally{liveRequest=false}}
function connectLive(){stopLive();pullLive();poll=setInterval(pullLive,2500);timer=setInterval(tick,250);if(sb&&live){channel=sb.channel('ilmora-'+live.id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'live_signals',filter:'id=eq.'+live.id},()=>pullLive()).subscribe()}}
function tick(){if(route!=='game'||!liveState?.deadline)return;let s=liveState,ms=Math.max(0,Date.parse(s.deadline)-(Date.now()+(s.offset||0)));let el=$('#seconds'),bar=$('#timebar');if(el)el.textContent=Math.ceil(ms/1000)+' s';if(bar)bar.style.width=Math.min(100,ms/(1000*Math.max(5,s.question?.time||30))*100)+'%';if(ms===0)pullLive()}
async function submitLive(){if(!liveState||liveState.mine?.submitted||!selected.length)return;let ch=[...selected];try{await api('live_answer',{p_room:live.id,p_token:live.token,p_choice:ch,p_index:liveState.index});await pullLive()}catch(err){fail(err);await pullLive()}}
function currentDoc(){if($('#doc-title'))doc.title=$('#doc-title').value;if($('#doc-body'))doc.body=$('#doc-body').value;return doc}
function download(name,content,type){let blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function printDoc(title,body){root.querySelector('.print-only')?.remove();let el=document.createElement('div');el.className='print-only';el.innerHTML=`<h1>${e(title)}</h1><p>${e(body)}</p>`;root.append(el);window.print()}
// Minimal standards-compatible OOXML archive, no external Word library required.
function docxBlob(title,body){let encoder=new TextEncoder();const xml=s=>e(s).replace(/\u0000/g,'');const p=s=>`<w:p><w:r><w:t xml:space="preserve">${xml(s)}</w:t></w:r></w:p>`;let files={'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>','_rels/.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>','word/document.xml':`<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${p(title)}${body.split('\n').map(p).join('')}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>`};let chunks=[],central=[],off=0,cs=0;const hdr=(n,entries)=>{let b=new Uint8Array(n),d=new DataView(b.buffer);for(let [o,v,w] of entries)w===2?d.setUint16(o,v,true):d.setUint32(o,v,true);return b};const crc=b=>{let c=0xffffffff;for(let x of b){c^=x;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0};for(let [name,text] of Object.entries(files)){let n=encoder.encode(name),b=encoder.encode(text),c=crc(b),h=hdr(30,[[0,0x04034b50,4],[4,20,2],[6,0x800,2],[14,c,4],[18,b.length,4],[22,b.length,4],[26,n.length,2]]),ch=hdr(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[8,0x800,2],[16,c,4],[20,b.length,4],[24,b.length,4],[28,n.length,2],[42,off,4]]);chunks.push(h,n,b);central.push(ch,n);off+=h.length+n.length+b.length;cs+=ch.length+n.length}return new Blob([...chunks,...central,hdr(22,[[0,0x06054b50,4],[8,3,2],[10,3,2],[12,cs,4],[16,off,4]])],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
async function saveChat(){if(!messages.length)return;let obj={title:messages[0].text.slice(0,100),messages,updated_at:new Date().toISOString()};if(demo){let a=get('demo-chats',[]);if(!chatId)chatId=crypto.randomUUID();a=a.filter(x=>x.id!==chatId);a.unshift({...obj,id:chatId});save('demo-chats',a)}else{if(chatId)await query('ai_conversations',q=>q.update(obj).eq('id',chatId));else chatId=(await query('ai_conversations',q=>q.insert(obj).select('id').single())).id}await loadData('ai')}
function fallback(prompt){let p=prompt.toLowerCase();let l=lessons.find(l=>p.includes(l.title.toLowerCase())||l.items.some(x=>p.includes(x[0].toLowerCase())));if(l){let item=l.items.find(x=>p.includes(x[0].toLowerCase()));if(item)return `Mahalliy o‘quv materiali (AI emas):\n${item[0]} — ${item[1]}.\nMisol: ${item[2]}${l.module?`\nManba: ${l.module}-ma’ruza, ${l.pages}-sahifalar.`:""}`;return `Mahalliy o‘quv materiali (AI emas):\n${l.intro}\n${l.items.map(x=>x[0]+' — '+x[1]).join('\n')}`}let s=textStats(prompt);return `Mahalliy tavsiya (AI emas): ${s.words} so‘z, ${s.sentences} gap. Akademik matnda kirish, asosiy qism va xulosani ajrating; da’voni dalillar bilan asoslang va manbalarni belgilang. Gemini sozlanmagan yoki limiti tugagan bo‘lishi mumkin.`}
async function sendAI(f,form){if(busyAI)return;let prompt=f.get('prompt').trim();if(!prompt)return;if(!f.get('consent'))throw Error('AI xizmatiga yuborishdan oldin rozilik bering.');aiAssignment=f.get('assignment')||'';let file=f.get('pdf');let pdf=null;if(file?.size){if(file.size>2*1024*1024||file.type!=='application/pdf')throw Error('PDF 2 MB gacha bo‘lsin.');pdf=await new Promise((res,rej)=>{let rd=new FileReader();rd.onload=()=>res(rd.result.split(',')[1]);rd.onerror=rej;rd.readAsDataURL(file)})}messages.push({role:'user',text:prompt});data.aiDraft='';busyAI=true;render();try{let reply;if(demo){reply=fallback(prompt)}else{let sess=(await sb.auth.getSession()).data.session;let response=await fetch('/.netlify/functions/ai',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+sess.access_token},body:JSON.stringify({tool:aiTool,messages:messages.slice(-10),assignment:aiAssignment,consent:true,pdf})});let j=await response.json().catch(()=>({}));if(!response.ok){reply=(response.status===403?'AI ruxsati: '+(j.error||'Bu topshiriqda AI o‘chirilgan.'):(j.error||'AI vaqtincha ishlamayapti.')+'\n\n'+fallback(prompt))}else reply=j.text}messages.push({role:'assistant',text:reply});await saveChat()}catch(err){messages.push({role:'assistant',text:'AI bilan ulanishda xato. '+fallback(prompt)});try{await saveChat()}catch{}}finally{busyAI=false;if(route==='ai')render()}}
async function action(a,id){if(a.startsWith('goto-'))return go(a.slice(5));switch(a){case 'lesson-view':lessonShort=!lessonShort;render();break;case 'focus':focusMode=!focusMode;render();break;case 'lesson-cards':cardIndex=lessons.findIndex(l=>l.id===+id)*5;cardFlip=false;go('cards');break;case 'lesson-mini':labMode='match';labLesson=+id;miniIndex=0;miniPick=null;go('labs');break;case 'lab-mode':labMode=id;miniIndex=0;miniPick=null;render();break;case 'mini-answer':miniPick=+id;render();break;case 'mini-next':miniIndex++;miniPick=null;if(miniIndex>=5){toast('5 ta atama mashqi yakunlandi!');miniIndex=0;}render();break;case 'lab-analyze':analyzeLab();break;case 'lab-save':save(personKey('notes'),$('#lab-text').value);toast('Konspekt shu qurilmada saqlandi');break;case 'lab-timer':runSpeechTimer();break;case 'module-open':go('lessons');setTimeout(()=>document.querySelector('[data-module=\"'+id+'\"]')?.scrollIntoView({behavior:'smooth'}),300);break;case 'exam-mid':startSpecial(lessons.filter(l=>l.module>=1&&l.module<=3).map(l=>l.id),20);break;case 'exam-final':startSpecial(lessons.filter(l=>l.module).map(l=>l.id),30);break;case 'retry-mistakes':{let qs=bank.filter(q=>get(personKey('mistakes'),[]).includes(q.id));if(!qs.length)return;practice={qs:qs.slice(0,30),index:0,score:0,pick:null,done:false};go('practice');break;} case 'menu':$('#side')?.classList.toggle('open');break;case 'theme':theme=theme==='light'?'dark':'light';save('theme',theme);document.body.classList.toggle('dark',theme==='dark');break;case 'home':go(user||demo?'home':'landing');break;case 'login':case 'signup':case 'reset':authMode=a;go('auth');break;case 'demo':startDemo();break;case 'logout':stopLive();live=null;liveState=null;save('live',null);if(sb&&user)await sb.auth.signOut();demo=false;user=null;profile=null;data={};doc=null;messages=[];builder=[];practice=null;go('landing');break;case 'google':if(!sb)throw Error('Supabase sozlanmagan.');{let {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/'}});if(error)throw error}break;case 'join':go('join');break;case 'continue':{let n=lessons.find(l=>!data.progress?.includes(l.id));go('lesson/'+(n?.id||1));break}case 'lesson':if(get('lesson-mode','free')==='ordered'&&lessons.slice(0,lessons.findIndex(l=>l.id===+id)).some(l=>!data.progress?.includes(l.id)))throw Error('Avval oldingi darsni tugating.');go('lesson/'+id);break;case 'complete':if(demo){let arr=get('demo-progress',[]);if(!arr.includes(+id)){arr.push(+id);profile.xp+=50;save('demo-profile',profile);save('demo-progress',arr)}}else{await api('complete_lesson',{p_lesson:+id});await refreshProfile()}await refresh();toast('Dars tugallandi! +50 XP');break;case 'delete-comment':await query('lesson_comments',q=>q.delete().eq('id',id));await refresh();break;case 'practice-all':startPractice();break;case 'practice-lesson':startPractice(+id);break;case 'practice-reset':practice=null;render();break;case 'practice-answer':if(practice.pick===null){practice.pick=+id;let q=practice.qs[practice.index],ok=q.answer.includes(+id),old=get(personKey('mistakes'),[]);if(ok)practice.score++;save(personKey('mistakes'),ok?old.filter(x=>x!==q.id):[...new Set([...old,q.id])]);render()}break;case 'practice-next':if(practice.pick===null)return;if(++practice.index>=practice.qs.length)practice.done=true;practice.pick=null;render();break;case 'clear-builder':builder=[];editingQuiz=null;render();break;case 'remove-q':builder.splice(+id,1);render();break;case 'load-quiz':{let q=data.quizzes.find(x=>x.id===id);builder=structuredClone(q.questions);editingQuiz={...q,id:demo||q.owner===user?.id?q.id:null};render();let input=$('[data-form="quiz-save"] [name="title"]');input.value=q.title;break}case 'delete-quiz':if(!confirm('Test o‘chirilsinmi?'))break;if(demo)save('demo-quizzes',get('demo-quizzes',[]).filter(x=>x.id!==id));else await query('quizzes',q=>q.delete().eq('id',id));await refresh();break;case 'exam-host':await hostGame('Akademik yozuv — imtihon',[...bank].sort(()=>Math.random()-.5).slice(0,10),{exam:true});break;case 'quick-host':await hostGame('Akademik yozuv — tezkor test',[...bank].sort(()=>Math.random()-.5).slice(0,10),{});break;case 'resume-host':live={id,host:true};liveState=null;save('live',live);go('game');break;case 'demo-game':startDemo();startPractice(1);break;case 'copy-join':await navigator.clipboard.writeText(location.origin+'/?pin='+liveState.pin+'#join');toast('Havola nusxalandi');break;case 'kick':await api('live_control',{p_room:live.id,p_action:'kick',p_player:id});await pullLive();break;case 'live-start':case 'live-reveal':case 'live-next':case 'live-finish':await api('live_control',{p_room:live.id,p_action:a.slice(5)});await pullLive();break;case 'live-pick':if(liveState.question.type==='multiple'){selected=selected.includes(+id)?selected.filter(x=>x!==+id):[...selected,+id];render()}else{selected=[+id];render();await submitLive()}break;case 'live-submit':await submitLive();break;case 'leave-live':stopLive();live=null;liveState=null;selected=[];save('live',null);go(user||demo?'live':'landing');break;case 'report-download':{let csv='O‘rin,Ism,Ball\n'+liveState.players.map((p,i)=>`${i+1},"${(/^[=+@-]/.test(p.name)?"'":'')+p.name.replace(/"/g,'""')}",${p.score}`).join('\n');download('ilmora-natija.csv','\ufeff'+csv,'text/csv');break}case 'doc-new':doc={id:null,title:'Yangi hujjat',body:''};render();break;case 'template':case 'library-template':if(a==='template'&&currentDoc().body&&!confirm('Joriy matn shablon bilan almashtirilsinmi?'))return;doc={id:null,title:id,body:templates[id]};if(a==='library-template')go('writing');else render();break;case 'doc-save':{let d=currentDoc(),obj={title:d.title.trim()||'Hujjat',body:d.body,updated_at:new Date().toISOString()};if(demo){d.id=d.id||crypto.randomUUID();let arr=get('demo-docs',[]).filter(x=>x.id!==d.id);arr.unshift({...obj,id:d.id});save('demo-docs',arr)}else if(d.id)await query('documents',q=>q.update(obj).eq('id',d.id));else d.id=(await query('documents',q=>q.insert(obj).select('id').single())).id;toast('Hujjat saqlandi');await refresh();break}case 'doc-open':doc={...data.docs.find(x=>x.id===id)};render();break;case 'doc-delete':if(!confirm('Hujjat o‘chirilsinmi?'))return;if(demo)save('demo-docs',get('demo-docs',[]).filter(x=>x.id!==id));else await query('documents',q=>q.delete().eq('id',id));if(doc.id===id)doc=null;await refresh();break;case 'doc-print':{let d=currentDoc();printDoc(d.title,d.body);break}case 'doc-word':{let d=currentDoc();download((d.title.replace(/[^\p{L}\p{N}_-]/gu,'-')||'ilmora')+'.docx',docxBlob(d.title,d.body));break}case 'doc-share':{if(!confirm('Havolani olgan, tizimga kirgan har qanday foydalanuvchi hujjatni o‘qiy oladi. Davom etilsinmi?'))return;let t=await api('share_document',{p_id:doc.id});let link=location.origin+'/#shared/'+t;try{await navigator.clipboard.writeText(link);toast('Ulashish havolasi nusxalandi')}catch{prompt('Ulashish havolasi',link)}break}case 'doc-unshare':await api('revoke_document_share',{p_id:doc.id});toast('Havola bekor qilindi');break;case 'shared-print':printDoc(data.sharedDoc.title,data.sharedDoc.body);break;case 'approve-lesson':case 'reject-lesson':await api('review_lesson',{p_id:id,p_approve:a==='approve-lesson'});await refresh();break;case 'doc-ai':data.aiDraft=currentDoc().body;aiTool='review';go('ai');break;case 'ai-import':{let raw=messages.at(-1)?.text||'';let m=raw.match(/\[[\s\S]*\]/);if(!m)throw Error('AI JSON formatida test qaytarmadi.');let qs=JSON.parse(m[0]);if(!Array.isArray(qs)||!qs.length||qs.length>100||qs.some(q=>typeof q.question!=='string'||!Array.isArray(q.options)||q.options.length<2||q.options.length>6||q.options.some(o=>typeof o!=='string')||!Array.isArray(q.answer)||!q.answer.length||q.answer.some(i=>!Number.isInteger(i)||i<0||i>=q.options.length)))throw Error('Test formati noto‘g‘ri. AI dan qayta yaratishni so‘rang.');builder=qs.map(q=>({question:q.question,options:q.options,answer:[...new Set(q.answer)],type:q.answer.length>1?'multiple':'choice',time:Math.max(5,Math.min(120,Number(q.time)||30)),explanation:String(q.explanation||'')}));editingQuiz=null;go('studio');toast('Test import qilindi. Har bir javobni tekshiring.');break}case 'ai-tool':aiTool=id;render();break;case 'ai-new':messages=[];chatId=null;render();break;case 'chat-open':{let c=data.chats.find(x=>x.id===id);chatId=id;messages=c.messages;render();break}case 'card-flip':cardFlip=!cardFlip;render();break;case 'card-prev':cardIndex=(cardIndex+lessons.length*5-1)%(lessons.length*5);cardFlip=false;render();break;case 'card-next':cardIndex=(cardIndex+1)%(lessons.length*5);cardFlip=false;render();break;case 'certificate':if(data.progress.length===lessons.length)printDoc('ILMORA — Kursni tugatish sertifikati',`${profile.name}\nAkademik yozuv bo‘yicha ${lessons.length} ta mavzuni yakunladi.\nSana: ${new Date().toLocaleDateString('uz-UZ')}\nILMORA ichki o‘quv sertifikati.`);break;case 'teacher-request':await ensureAuth();await api('request_teacher');await refresh();toast('Ariza yuborildi');break;case 'approve':case 'reject':await api('review_teacher',{p_id:id,p_approve:a==='approve'});await refresh();break;case 'notice-read':await query('notifications',q=>q.update({read_at:new Date().toISOString()}).eq('id',id));await refresh();break;}}
async function formAction(name,form,submitter){let f=new FormData(form),v=k=>String(f.get(k)||'').trim();switch(name){case 'auth':{if(!sb)throw Error('Avval Supabase sozlanishi kerak.');let result;if(authMode==='signup')result=await sb.auth.signUp({email:v('email'),password:v('password'),options:{data:{name:v('name')},emailRedirectTo:location.origin+'/'}});else if(authMode==='reset')result=await sb.auth.resetPasswordForEmail(v('email'),{redirectTo:location.origin+'/'});else if(authMode==='newpass')result=await sb.auth.updateUser({password:v('password')});else result=await sb.auth.signInWithPassword({email:v('email'),password:v('password')});if(result.error)throw result.error;if(authMode==='signup'&&!result.data.session)toast('Emailingizga tasdiqlash havolasi yuborildi.');else if(authMode==='reset')toast('Emailingizni tekshiring.');else if(authMode==='newpass'){authMode='login';go('home')}break}case 'bank-add':{let qs=bank.filter(q=>q.lesson===+v('lesson')).slice(0,+v('count'));if(builder.length+qs.length>100)throw Error('Testda ko‘pi bilan 100 ta savol.');builder.push(...qs);render();break}case 'question-add':{let opts=v('options').split('\n').map(s=>s.trim()).filter(Boolean),answer=[...new Set(v('answer').split(',').map(s=>Number(s.trim())-1))];if(opts.length<2||opts.length>6||!answer.length||answer.some(n=>!Number.isInteger(n)||n<0||n>=opts.length)||v('type')!=='multiple'&&answer.length!==1)throw Error('2–6 variant va to‘g‘ri javob raqamlarini tekshiring.');if(builder.length>=100)throw Error('100 savol limiti.');if(v('mediaType')&&!safeURL(v('mediaUrl')))throw Error('Media uchun HTTPS havolasi kerak.');builder.push({question:v('question'),options:opts,answer,type:v('type'),time:+v('time'),explanation:v('explanation'),mediaType:v('mediaType'),mediaUrl:v('mediaUrl')});render();break}case 'quiz-save':{if(!builder.length)throw Error('Savollar qo‘shing.');let obj={title:v('title'),questions:builder,is_public:f.has('public')};let settings={auto:f.has('auto'),late:f.has('late'),projector:f.has('projector'),exam:f.has('exam')};if(submitter?.value==='live'){await hostGame(obj.title,builder,settings)}else{if(demo){let arr=get('demo-quizzes',[]).filter(x=>x.id!==editingQuiz?.id);let id=editingQuiz?.id||crypto.randomUUID();arr.unshift({...obj,id});save('demo-quizzes',arr);editingQuiz={...obj,id}}else if(editingQuiz?.id)await query('quizzes',q=>q.update(obj).eq('id',editingQuiz.id));else editingQuiz=(await query('quizzes',q=>q.insert(obj).select('*').single()));toast('Test saqlandi');await refresh()}break}case 'join':{if(!sb)throw Error('Haqiqiy o‘yin uchun Supabase ulang.');let r=await api('live_join',{p_pin:v('pin'),p_name:v('name')});live={id:r.id,token:r.token,pin:r.pin,host:false};liveState=null;save('live',live);go('game');break}case 'comment':await query('lesson_comments',q=>q.insert({lesson_id:lessonId,body:v('body')}));await refresh();break;case 'ai':await sendAI(f,form);break;case 'citation':{let str=v('style')==='apa'?`${v('author')} (${v('year')}). ${v('title')}. ${v('publisher')}.`:`${v('author')}. ${v('title')}. ${v('publisher')}, ${v('year')}.`;$('#citation-output').innerHTML=`<div class="notice">${e(str)}<br><small>Kitob nomi yakuniy hujjatda kursiv bo‘lishi kerak.</small></div><button class="btn secondary" id="copy-cite">Nusxalash</button>`;$('#copy-cite').onclick=()=>navigator.clipboard.writeText(str).then(()=>toast('Nusxalandi'));break}case 'profile':{let obj={name:v('name'),nickname:v('nickname')};if(demo){Object.assign(profile,obj);save('demo-profile',profile)}else{await query('profiles',q=>q.update(obj).eq('id',user.id));await refreshProfile()}await refresh();toast('Profil saqlandi');break}case 'lesson-create':await ensureAuth();if(v('scope')==='class'&&!v('class_id'))throw Error('Guruhni tanlang.');if(v('video')&&!safeURL(v('video')))throw Error('HTTPS havolasi kerak.');await api('create_lesson',{p_title:v('title'),p_body:v('body'),p_video:v('video'),p_scope:v('scope'),p_class:v('class_id')||null});await refresh();toast('Dars yuborildi');break;case 'class-create':await ensureAuth();await query('classes',q=>q.insert({title:v('title')}));await refresh();break;case 'class-join':await ensureAuth();await api('join_class',{p_code:v('code')});await refresh();break;case 'class-add':await api('add_class_member',{p_class:form.dataset.id,p_email:v('email')});toast('A’zo qo‘shildi');form.reset();break;case 'assignment-create':await ensureAuth();if(!v('class_id'))throw Error('Avval guruh yarating.');await query('assignments',q=>q.insert({class_id:v('class_id'),title:v('title'),description:v('description'),due_at:v('due')?new Date(v('due')).toISOString():null,scale:+v('scale'),ai_policy:v('policy')}));await refresh();break;case 'submit-assignment':await query('submissions',q=>q.insert({assignment_id:form.dataset.id,body:v('body')}));await refresh();break;case 'grade':await api('grade_submission',{p_id:form.dataset.id,p_grade:+v('grade'),p_comment:v('comment')});await refresh();break;case 'feedback':await ensureAuth();await query('feedback',q=>q.insert({body:v('body')}));form.reset();toast('Xabar yuborildi');break;}}
root.addEventListener('click',ev=>{let piece=ev.target.closest('[data-piece]');if(piece){piece.dataset.selected='1';piece.disabled=true;let list=$('#puzzle-list');list.append(piece);let chosen=[...list.querySelectorAll('[data-selected]')].map(x=>+x.dataset.piece);if(chosen.length===3){$('#lab-result').textContent=chosen.join(',')==='1,2,0'?'✓ To‘g‘ri tartib!':'To‘g‘ri tartib: Kitob o‘qish… → O‘qish jarayonida… → Shu sababli…';}return;}let b=ev.target.closest('[data-act],[data-go]');if(!b||b.disabled)return;if(b.dataset.go){go(b.dataset.go);return}if(b.dataset.act){ev.preventDefault();Promise.resolve(action(b.dataset.act,b.dataset.id)).catch(fail)}});
root.addEventListener('submit',ev=>{let f=ev.target;if(!f.dataset.form)return;ev.preventDefault();let b=ev.submitter;if(b)b.disabled=true;Promise.resolve(formAction(f.dataset.form,f,b)).catch(fail).finally(()=>{if(b&&b.isConnected)b.disabled=false})});
root.addEventListener('input',ev=>{if(route==='writing'&&['doc-title','doc-body'].includes(ev.target.id)){currentDoc();save(demo?'demo-draft':'draft-'+user?.id,doc);let s=$('#text-stats');if(s)s.innerHTML=statHTML(doc.body)}});
root.addEventListener('change',ev=>{if(ev.target.name==='lesson-mode')save('lesson-mode',ev.target.value)});
window.addEventListener('hashchange',navigate);
async function init(){if(configured){try{await new Promise((resolve,reject)=>{let script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.49.4/dist/umd/supabase.js';script.onload=resolve;script.onerror=()=>reject(Error('Supabase SDK yuklanmadi'));document.head.append(script)});sb=window.supabase.createClient(config.supabaseUrl,config.supabaseKey);let {data:{session}}=await sb.auth.getSession();user=session?.user||null;if(user){await refreshProfile();doc=get('draft-'+user.id,null)}sb.auth.onAuthStateChange((event,session)=>{if(event==='INITIAL_SESSION')return;setTimeout(async()=>{try{let old=user?.id;user=session?.user||null;if(event==='PASSWORD_RECOVERY'){authMode='newpass';go('auth');return}if(event==='TOKEN_REFRESHED')return;if(user){if(old!==user.id){data={};doc=get('draft-'+user.id,null);messages=[];builder=[]}await refreshProfile();demo=false;if(!old||['auth','landing'].includes(route)){let ret=sessionStorage.getItem('ilmora-return');sessionStorage.removeItem('ilmora-return');go(ret||'home');}else if(old!==user.id)navigate()}else if(old){data={};profile=null;go('landing')}}catch(err){fail(err)}},0)})}catch(err){fail(err)}}authReady=true;await navigate()}
// Render the public screen immediately; authenticated pages wait for session lookup.
route=location.hash==='#join'?'join':'landing';render();init();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(console.warn);
